import type {Costume} from '../services/PlayerStore';
/** Small silhouettes layered on the shared avatar grid; variant colors come from catalog. */
export function costumePatterns(rows:string[],colors:Record<string,string>,items:Partial<Record<string,Costume>>){
 const put=(y:number,x:number,s:string)=>{rows[y]=rows[y].slice(0,x)+s+rows[y].slice(x+s.length);};
 const style=(slot:string)=>items[slot]?.style;
 const hair=style('hair');if(hair!==undefined){
  const crowns=['..hhhhhhhh..','...hhhhhh...','.....hh.....','..hhh.hhh...','...h.h.h....','..hhhhhh....','.hhhhhhhhhh.','..hhhhhhhh..','..hhhhhhhh..','...hhhhhhh..'];
  rows[0]=crowns[hair%10];rows[1]=hair%10===2?'....hhhh....':'..hhhhhhhh..';
  if([3,5,8].includes(hair%10)){put(2,1,'hh');put(4,1,'hh');put(5,1,'hh');if(hair%10===8){put(2,9,'hh');put(4,9,'hh');put(5,9,'hh');}}
  if(hair>=10){colors.u='#f9e3ad';put(1,3,'u');}
 }
 const top=style('top');if(top!==undefined){
  if(top%5===0){put(7,4,'wttw');put(8,5,'ww');}
  if(top%5===1){put(7,2,'wwwwwwww');put(9,3,'wwwwww');}
  if(top%5===2){put(7,5,'ww');put(8,4,'ww');put(9,5,'w');}
  if(top%5===3){put(6,3,'kkkkkk');put(7,3,'wttttw');put(8,3,'wkwtkw');put(9,3,'wwwwww');}
  if(top%5===4){put(6,3,'wwttww');put(7,4,'wttw');put(8,4,'tttt');}
 }
 const pants=style('pants');if(pants!==undefined){
  rows[12]=pants%5===1?'...ss..ss...':'...dd..dd...';
  if(pants%5===0){put(10,4,'kddk');put(11,4,'wd');}
  if(pants%5===2){put(11,3,'dw..wd');put(12,3,'dw..wd');}
  if(pants%5===3){put(10,3,'wddddw');put(12,3,'ww..ww');}
  if(pants%5===4||pants===5||pants===16){rows[10]='..dddddddd..';rows[11]='..dwdwdwdd..';rows[12]='...ss..ss...';}
 }
 const jacket=style('jacket');if(jacket!==undefined){
  if([0,5,8,13,17].includes(jacket)){rows[7]='jjjjjttjjjjj';rows[8]='jjjjttttjjjj';rows[10]='jjjddddddjjj';if(jacket===5||jacket===8){rows[6]='jjjjjttjjjjj';rows[9]='jj.tttttt.jj';}}
  if(jacket%5===1){put(7,2,'wj');put(7,8,'jw');put(9,3,'wwttww');}
  if(jacket%5===2){put(6,3,'wjttjw');put(7,4,'wttw');}
  if(jacket===3||jacket===14){put(7,0,'aj');put(7,10,'ja');put(9,0,'aj');put(9,10,'ja');}
  if(jacket%5===4){rows[6]='jjjjjttjjjjj';put(7,2,'aw');put(7,8,'wa');}
 }
 const hat=style('hat');if(hat!==undefined){
  const shapes=[['..c..cc..c..','..cccccccc..'],['..cc....cc..','..cc....cc..'],['.ccc....ccc.','.cc......cc.'],['.....cc.....','.cccccccccc.'],['.....c......','....ccc.....'],['..aaaaaaaa..','............'],['..cc....cc..','...cc..cc...'],['.....a......','.....c......'],['..cc....cc..','..ckcccckc..'],['....cccc....','..cccccccc..'],['...accca....','..cccccccc..'],['..acacaaca..','...cccccc...'],['...cccccc...','..ccckkccc..'],['..cccccccc..','.ccc....ccc.'],['..cccccccc..','..ckkkkkkc..'],['....cccc....','....cccc....'],['...a........','..aa.hh.....'],['..c..c..c...','..cccccccc..'],['.....cc.....','cccccccccc..'],['...a........','..ccc.......']];
  rows[0]=shapes[hat][0];rows[1]=shapes[hat][1];
 }
 const glasses=style('glasses');if(glasses!==undefined){const patterns=['..sggssggs..','..sggggggs..','..gggggggg..','..sgggsss...','..ggkggkgg..','..sssssggs..','..gwwggwwg..','..gggggggg..','..ggkggkgg..','..gwgwgwgw..'];rows[3]=patterns[glasses%10];}
 const ears=style('earrings');if(ears!==undefined){put(4,1,'e');put(4,10,'e');if(ears%3===0){put(5,1,'e');put(5,10,'e');}if(ears%3===1){put(4,0,'ee');put(4,10,'ee');}if(ears%3===2){put(5,0,'e');put(5,11,'e');}}
 const neck=style('necklace');if(neck!==undefined){
  if(neck%4===0){put(6,4,'nssn');put(7,5,'nn');put(8,5,'aa');}
  if(neck%4===1){put(6,3,'nnnnnn');put(7,5,'aa');}
  if(neck%4===2){put(6,4,'nnnn');put(7,5,'nn');put(8,5,'nn');put(9,5,'n');}
  if(neck%4===3){put(6,3,'nnnnnn');put(7,3,'nn');put(8,3,'nn');}
 }
 const shoes=style('shoes');if(shoes!==undefined){
  if(shoes%5===0){rows[13]='..ffw..ffw..';}
  if(shoes%5===1){rows[13]='..wff..wff..';}
  if(shoes%5===2){rows[13]='..faf..faf..';}
  if(shoes%5===3){rows[12]='...ff..ff...';rows[13]='..fff..fff..';}
  if(shoes%5===4){rows[13]='.ffff..ffff.';}
 }
}
