/** Low-detail social-slot scenery. Feature props and the host stay outside the reel focus. */
function socialBackdrop(parent:Node,layer:number,width:number,height:number,spec:SocialSlotSpec):void{
 const node=new Node('Social theme backdrop '+spec.id);node.layer=layer;parent.addChild(node);node.addComponent(UITransform).setContentSize(width,height);const g=node.addComponent(Graphics);
 const rect=(x:number,y:number,w:number,h:number,color:string)=>{g.fillColor=new Color(color);g.rect(Math.round(x),Math.round(height-y-h),Math.ceil(w),Math.ceil(h));g.fill();};
 rect(0,0,width,height,spec.colors[0]);rect(0,height*.66,width,height*.34,'#263747');
 // Flat feature props distinguish the five mechanics without adding visual noise.
 if(spec.mechanic==='link')for(let i=0;i<8;i++){const x=24+(i%4)*38,y=110+Math.floor(i/4)*38;rect(x,y,22,22,'#17243a');rect(x+4,y+4,14,14,i%2?spec.colors[1]:spec.colors[2]);}
 else if(spec.mechanic==='sticky'){rect(0,84,30,height*.52,spec.colors[1]);rect(width-30,84,30,height*.52,spec.colors[1]);for(let i=0;i<5;i++)rect(48+i*42,110+(i%2)*18,8,8,spec.colors[2]);}
 else if(spec.mechanic==='collector')for(let i=0;i<9;i++){const x=20+(i%3)*34,y=120+Math.floor(i/3)*34;rect(x,y,18,18,'#17243a');rect(x+4,y+4,10,10,spec.colors[1]);}
 else if(spec.mechanic==='expanding')for(let i=0;i<4;i++){rect(18+i*34,112,26,78,'#17243a');rect(22+i*34,116,18,70,i%2?spec.colors[1]:spec.colors[2]);}
 else for(let i=0;i<7;i++){const x=18+i*30,y=118+(i%2)*26;rect(x,y,5,22,spec.colors[2]);rect(x-8,y+8,21,5,spec.colors[2]);}
 // Add a host only after the source game's reel background has been reviewed.
 // This prevents a catalog hero name from automatically becoming background clutter.
 const reviewedCharacterBackdrops=new Set(['double-lucky','take-five-jackpot']);
 if(reviewedCharacterBackdrops.has(spec.id)){
  const right=width>700,x=right?width-132:width-92,y=Math.max(92,height*.16),dealer=spec.id==='double-lucky';
  const skin=dealer?'#d9a077':'#b97b58',hair=dealer?'#4b2f35':'#332a2c',clothes=dealer?'#f2e7ce':'#c84343';
  rect(x+20,y,32,10,hair);rect(x+14,y+9,44,34,hair);rect(x+20,y+15,32,30,skin);rect(x+25,y+23,5,5,'#17243a');rect(x+43,y+23,5,5,'#17243a');rect(x+32,y+34,10,4,'#9d4d52');
  if(!dealer){rect(x+10,y-4,52,9,'#8f3038');rect(x+18,y-12,36,9,'#c84343');}
  rect(x+13,y+48,46,58,clothes);rect(x+1,y+52,14,48,skin);rect(x+58,y+52,14,48,skin);rect(x+18,y+106,14,58,'#26334b');rect(x+40,y+106,14,58,'#26334b');
  if(dealer){rect(x+31,y+48,10,15,'#a5374d');rect(x+25,y+48,22,5,'#fff3db');}
  const px=x+(right?-12:72),py=y+58;rect(px,py,22,22,'#17243a');rect(px+4,py+4,14,14,spec.colors[1]);
 }
}
/** Lightweight, static pixel scenery. Dense decoration stays outside the reels. */
export function forestBackdrop(parent:Node,layer:number,width:number,height:number):void{
 const node=new Node('Pixel forest backdrop');node.layer=layer;parent.addChild(node);node.addComponent(UITransform).setContentSize(width,height);const g=node.addComponent(Graphics);
 function rect(x:number,y:number,w:number,h:number,color:string){g.fillColor=new Color(color);g.rect(Math.round(x),Math.round(height-y-h),Math.ceil(w),Math.ceil(h));g.fill();}
 rect(0,0,width,height,'#233c43');rect(0,0,width,height*.25,'#242f43');rect(0,height*.25,width,height*.28,'#263e48');rect(0,height*.7,width,height*.3,'#29443e');
 // Layered stepped silhouettes, rather than a smooth high-resolution gradient.
 for(let i=0;i<Math.ceil(width/32);i++){const x=i*32,y=height*.27+((i*17)%5)*8;rect(x,y,32,height*.17,'#293f48');}
 function tree(x:number,y:number,s:number,shade:string){rect(x-4*s,y,8*s,130*s,'#263c3a');rect(x-26*s,y-35*s,52*s,44*s,shade);rect(x-38*s,y-15*s,76*s,42*s,shade);rect(x-22*s,y-49*s,44*s,26*s,shade);rect(x-29*s,y-28*s,16*s,8*s,'#3f6052');}
 for(let i=0;i<4;i++){tree(14+i*15,height*.24+i*height*.18,.8+(i%2)*.25,i%2?'#345449':'#304b45');tree(width-16-i*14,height*.31+i*height*.16,.8+(i%2)*.3,i%2?'#345449':'#304b45');}
 for(let i=0;i<46;i++){const side=i%2,x=side?width-12-(i*37)%74:12+(i*29)%74,y=108+(i*97)%Math.max(1,height-150);rect(x,y,3,3,i%4?'#587360':'#c3ac65');if(i%7===0){rect(x-3,y+1,9,2,'#89996a');rect(x+1,y-3,2,9,'#89996a');}}
 for(let i=0;i<Math.ceil(width/24);i++){const x=i*24,y=height-10-(i%3)*7;rect(x,y,24,40,'#1a302f');rect(x+8,y-8,8,14,'#314e40');}
}
