import type {RankingRound,RankRow,RankMetric} from './WeeklyRanking';
export const MIN_RANK_SPINS=10000,WEEK_MS=7*86400000;
export function rankingWeek(now:number){const date=new Date(now+9*3600000);return Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate()-(date.getUTCDay()+6)%7)-9*3600000;}
export interface WeeklyStats {name:string;spins:number;wins:number;moneyOut:number;bestBet:number;bestPayout:number;winRate:number;bigWin:number;weekStart:number;}
export function addRankRounds(old:WeeklyStats|undefined,rounds:RankingRound[],weekStart:number):WeeklyStats{
 const next=old?{...old}:{name:'게스트',spins:0,wins:0,moneyOut:0,bestBet:1,bestPayout:0,winRate:-1,bigWin:0,weekStart};
 for(const r of rounds){next.name=r.name;next.spins++;if(r.payout>r.bet)next.wins++;next.moneyOut+=r.payout;if(r.payout/r.bet>next.bigWin){next.bestBet=r.bet;next.bestPayout=r.payout;next.bigWin=r.payout/r.bet;}}
 next.winRate=next.spins>=MIN_RANK_SPINS?next.wins/next.spins:-1;return next;
}
export function rankRows(entries:{id:string;stats:WeeklyStats}[],metric:RankMetric,uid:string):RankRow[]{let rank=0,last=-Infinity;return entries.filter(e=>e.stats[metric]>=0).sort((a,b)=>b.stats[metric]-a.stats[metric]||a.id.localeCompare(b.id)).map((e,i)=>{const value=e.stats[metric];if(value!==last)rank=i+1;last=value;return{rank,name:e.stats.name,value,spins:e.stats.spins,isMe:e.id===uid};});}
