import {SlotMain,SpinResult} from './SlotMain';
import {unscaledSpin} from './HitRatePolicy';
import {scalePayout} from './PayoutPolicy';
import {bonusMeans} from './BonusBuyConfig';
export const BONUS_COST_MULTIPLIER=20,BONUS_TICKET_TENTHS=150;
export function bonusKey(slot:SlotMain){const choice=(slot as SlotMain&{bonusChoice?:number}).bonusChoice;return slot.config.id+(choice===undefined?'':':'+choice);}
function triggerPresentation(slot:SlotMain,trigger:SpinResult):SpinResult{
 const bonus=slot.bonusSymbol,candidates=[trigger.openingBoard,...(trigger.cascades||[]).map(stage=>stage.board),trigger.board].filter((board):board is string[]=>!!board);
 const board=bonus?candidates.reduce((best,next)=>next.filter(id=>id===bonus).length>best.filter(id=>id===bonus).length?next:best,candidates[0]||trigger.board):trigger.board;
 // This is presentation only. The purchase RTP and settlement contain free-game rounds exclusively.
 return{bet:trigger.bet,board:[...board],wins:[],payout:0,roundLabel:'BONUS TRIGGER'};
}
export function sampleFreeGames(slot:SlotMain,bet:number,rng:()=>number):SpinResult{
 if(!slot.hasBonus)throw Error('No free games');
 for(let i=0;i<20000;i++){const natural=unscaledSpin(slot,bet,rng);if(!natural.rounds||natural.rounds.length<2)continue;const trigger=natural.rounds[0],rounds=natural.rounds.slice(1);return{bet,board:[...rounds[rounds.length-1].board],rounds,wins:rounds.flatMap(r=>r.wins),payout:rounds.reduce((n,r)=>n+r.payout,0),freeSpinsAwarded:rounds.length,featureName:natural.featureName,bonusTriggerRound:triggerPresentation(slot,trigger)};}
 throw Error('Free games could not be prepared');
}
export function buyBonusResult(slot:SlotMain,bet:number,rng:()=>number=Math.random){const mean=bonusMeans[bonusKey(slot)];if(!mean)throw Error('Bonus calibration unavailable');return scalePayout(sampleFreeGames(slot,bet,rng),BONUS_COST_MULTIPLIER*.98/mean,rng);}
