import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';
import {makeLines,sampleCells} from './FeatureKit';
import {socialSlotCatalog,SocialSlotSpec} from './SocialSlotCatalog';

const TAGS={link:'HOLD & LINK',sticky:'STICKY WILDS',collector:'COIN COLLECT',expanding:'EXPANDING WILD',multiplier:'MULTIPLIER'} as const;
const DEFAULT_PAYS=[[0,0,.5,2,12],[0,0,.4,1.5,8],[0,0,.3,1,5],[0,0,.25,.8,4],[0,0,.2,.6,3],[0,0,.15,.5,2],[0,0,.12,.4,1.5],[0,0,.1,.3,1]];

/** Five social-slot feature families rendered with the project's own pixel symbols. */
export class SocialFeatureSlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly hasBonus=true;readonly maxWin=10000;readonly paylines=makeLines(3,20);readonly config:SlotConfig;readonly pays:Record<string,number[]>={};readonly regularPays:number[][];
 get unlockPriceTenths(){return 1000;}get bonusSymbol(){return this.spec.id+'-scatter';}get wildSymbol(){return this.spec.id+'-wild';}
 get moneySymbol(){return this.spec.id+'-'+(this.spec.moneySymbolIndex??this.spec.symbols.length-1);}
 constructor(readonly spec:SocialSlotSpec){super();
  if(spec.symbols.length!==spec.arts.length)throw Error(`${spec.id}: symbol/art count mismatch`);
  this.regularPays=(spec.paytable??DEFAULT_PAYS.slice(0,spec.symbols.length)).map(row=>[...row]);
  if(this.regularPays.length!==spec.symbols.length||this.regularPays.some(row=>row.length!==5))throw Error(`${spec.id}: paytable must have one five-reel row per symbol`);
  const rules={
   link:['코인볼 6개 이상 → 3회 링크 보너스','새 코인볼마다 남은 횟수 3회 복구','가득 채우면 그랜드 잭팟'],
   sticky:['프리스핀에 등장한 와일드 고정','고정 와일드마다 ×2 또는 ×3','SCATTER 3개 → 프리스핀 10회'],
   collector:['머니 심볼을 메인 캐릭터가 수집','수집액에 컬렉터 수를 곱해 지급','SCATTER 3개 → 프리스핀 10회'],
   expanding:['선택된 캐릭터가 릴 전체로 확장','프리스핀마다 확장 심볼 재선택','SCATTER 3개 → 프리스핀 10회'],
   multiplier:['와일드 배수가 프리스핀 동안 누적','당첨 라인에 누적 배수 적용','SCATTER 3개 → 프리스핀 10회']
  }[spec.mechanic];
  this.config={id:spec.id,title:spec.title,subtitle:spec.subtitle,tag:spec.provider+' · '+TAGS[spec.mechanic],color:spec.colors[0],accent:spec.colors[1],description:[spec.hero,...rules].join('\n'),symbols:spec.symbols.map((name,i)=>({id:spec.id+'-'+i,name,art:spec.arts[i],color:i<2?spec.colors[1]:spec.colors[2],weight:10+i*2,payout:this.regularPays[i][4]})).concat([{id:this.bonusSymbol,name:'SCATTER',art:'star',color:'#fff0a8',weight:5.4,payout:0},{id:this.wildSymbol,name:'WILD',art:spec.mechanic==='collector'?'bag':'star',color:'#fff4bd',weight:3,payout:0}])};
  spec.symbols.forEach((_,i)=>this.pays[spec.id+'-'+i]=[...this.regularPays[i]]);
 }
 private evaluateBoard(board:string[],bet:number,values:number[]=Array(15).fill(1),shared=1):SpinResult{
  if(board.length!==15||!this.bets.includes(bet)||board.some(id=>!this.config.symbols.some(s=>s.id===id)))throw Error('Invalid social slot board');const wins:Win[]=[];
  this.paylines.forEach((line,index)=>{let best:Win|undefined;for(let s=0;s<this.regularPays.length;s++){const id=this.spec.id+'-'+s;let count=0,m=1;for(const cell of line){if(board[cell]!==id&&board[cell]!==this.wildSymbol)break;count++;if(board[cell]===this.wildSymbol)m*=Math.max(1,values[cell]||1);}const base=this.regularPays[s][count-1]||0,amount=Math.round(bet*base*(this.spec.mechanic==='sticky'?m:shared));if(amount&&(!best||amount>best.amount))best={line:index,symbol:id,cells:line.slice(0,count),amount,multiplier:this.spec.mechanic==='sticky'?m:shared};}if(best)wins.push(best);});
  return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),symbolValues:[...values]};
 }
 spin(bet:number,rng:()=>number=Math.random):SpinResult{
  const state={sticky:new Map<number,number>(),multiplier:1,held:new Set<number>()};const base=this.roll(bet,rng,false,state);state.sticky.clear();state.held.clear();state.multiplier=1;
  if(this.spec.mechanic==='link'&&base.board.filter(id=>id===this.bonusSymbol).length>=3)return this.linkBonus(base,bet,rng,state);
  return this.freeSpinSequence(base,()=>this.roll(bet,rng,true,state),round=>{const scatters=round.board.filter(id=>id===this.bonusSymbol).length;if(round===base)return scatters>=3?10:0;return scatters>=3?5:0;});
 }
 private linkBonus(base:SpinResult,bet:number,rng:()=>number,state:{sticky:Map<number,number>;multiplier:number;held:Set<number>}):SpinResult{
  let lives=3,played=0;const rounds=[base],values=Array<number>(15).fill(0);while(lives>0&&played<40&&state.held.size<15){played++;lives--;let added=0;for(let cell=0;cell<15;cell++)if(!state.held.has(cell)&&rng()<.105){state.held.add(cell);values[cell]=[1,2,2,3,5,10,20,50][Math.floor(rng()*rng()*8)];added++;}if(added)lives=3;
   const board=Array.from({length:15},(_,i)=>state.held.has(i)?this.moneySymbol:this.spec.id+'-'+Math.floor(rng()*this.spec.symbols.length)),round:SpinResult={board,bet,wins:[],payout:0,heldCells:Array.from(state.held),moneyCells:Array.from(state.held),symbolValues:[...values],featureText:'링크 코인 '+state.held.size+'/15',roundLabel:`LINK RESPIN · ${played}회 · 남은 ${lives}회`};rounds.push(round);
  }
  const final=rounds[rounds.length-1],multiple=Array.from(state.held).reduce((n,i)=>n+(values[i]||1),0),win:Win={line:-1,symbol:this.moneySymbol,cells:Array.from(state.held),amount:multiple*bet};final.wins=[win];final.payout=win.amount;
  return{board:[...final.board],bet,wins:rounds.flatMap(r=>r.wins),payout:rounds.reduce((n,r)=>n+r.payout,0),rounds,featureName:'HOLD & LINK',freeSpinsAwarded:3};
 }
 private roll(bet:number,rng:()=>number,free:boolean,state:{sticky:Map<number,number>;multiplier:number;held:Set<number>}):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');const values=Array<number>(15).fill(1);let board=Array.from({length:15},()=>this.pick(rng));
  if(free&&this.spec.mechanic==='sticky')for(const [cell,value] of state.sticky){board[cell]=this.wildSymbol;values[cell]=value;}
  board.forEach((id,i)=>{if(id!==this.wildSymbol)return;values[i]=rng()<.72?2:3;if(free&&this.spec.mechanic==='sticky')state.sticky.set(i,values[i]);});
  let expandedCells:number[]|undefined;
  if(free&&this.spec.mechanic==='expanding'){const chosen=this.spec.id+'-'+Math.floor(rng()*4),reels=new Set(board.map((id,i)=>id===chosen?i%5:-1).filter(i=>i>=0));expandedCells=[];for(const reel of reels)for(let row=0;row<3;row++){const at=row*5+reel;board[at]=this.wildSymbol;expandedCells.push(at);}}
  if(free&&this.spec.mechanic==='multiplier'){const additions=board.filter(id=>id===this.wildSymbol).length;if(additions)state.multiplier=Math.min(100,state.multiplier+additions+(rng()<.2?2:0));}
  const result=this.evaluateBoard(board,bet,values,this.spec.mechanic==='multiplier'&&free?state.multiplier:1);result.expandedCells=expandedCells;
  if(free&&this.spec.mechanic==='collector'){const money=board.map((id,i)=>id===this.moneySymbol?i:-1).filter(i=>i>=0),collectors=board.map((id,i)=>id===this.wildSymbol?i:-1).filter(i=>i>=0);money.forEach(i=>values[i]=[1,2,3,5,10,20][Math.floor(rng()*rng()*6)]);const multiple=money.reduce((n,i)=>n+values[i],0)*collectors.length;if(multiple){const win:Win={line:-1,symbol:this.wildSymbol,cells:[...money,...collectors],amount:multiple*bet};result.wins.push(win);result.payout+=win.amount;result.moneyCells=money;result.collectorCells=collectors;}result.featureText='캐릭터 수집 ×'+Math.max(1,collectors.length);}
  if(free&&this.spec.mechanic==='link'){for(const cell of board.map((id,i)=>id===this.moneySymbol?i:-1).filter(i=>i>=0))state.held.add(cell);for(const cell of state.held){board[cell]=this.moneySymbol;values[cell]=[1,2,3,5,10,20][Math.floor(rng()*rng()*6)];}const multiple=Array.from(state.held).reduce((n,i)=>n+values[i],0);if(multiple){const win:Win={line:-1,symbol:this.moneySymbol,cells:Array.from(state.held),amount:multiple*bet};result.wins.push(win);result.payout+=win.amount;}result.board=[...board];result.heldCells=Array.from(state.held);result.moneyCells=Array.from(state.held);result.featureText='링크 코인 '+state.held.size+'/15';}
  if(free&&this.spec.mechanic==='sticky'){result.heldCells=Array.from(state.sticky.keys());result.featureText='고정 와일드 '+state.sticky.size+'개';}
  if(free&&this.spec.mechanic==='expanding')result.featureText='캐릭터 확장 릴 '+(expandedCells?.length||0)/3+'개';
  if(free&&this.spec.mechanic==='multiplier')result.featureText='누적 배수 ×'+state.multiplier;
  return result;
 }
 demoSpin(bet:number){let seed=99173;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<5000;i++){const r=this.spin(bet,rng);if(r.payout>0&&!r.rounds)return r;}return super.demoSpin(bet);}
}
export const socialFeatureSlots=socialSlotCatalog.map(spec=>new SocialFeatureSlot(spec));
