export type LocalStorage = Pick<Storage, 'getItem' | 'setItem'>;
const legacyKey = 'midnight-slots-v1';
const ownerKey = 'midnight-slots-legacy-owner';

/** Keep local progress isolated by Firebase UID. Linking Google preserves the UID. */
export function accountStorage(storage: LocalStorage, uid: string): LocalStorage {
 if (!uid) throw new Error('Account ID required');
 const key = legacyKey + ':account:' + uid;
 // Claim the pre-Firebase save only once, leaving the original as a backup.
 // Write the owner before copying: an interrupted migration cannot clone a wallet.
 const owner = storage.getItem(ownerKey);
 if (!owner) storage.setItem(ownerKey, uid);
 if ((!owner || owner === uid) && storage.getItem(key) === null) {
  const legacy = storage.getItem(legacyKey);
  if (legacy !== null) storage.setItem(key, legacy);
 }
 return {
  getItem: () => storage.getItem(key),
  setItem: (_ignored, value) => storage.setItem(key, value),
 };
}
