/** KRW prices are provisional until matching products are registered in the stores. */
export const coinPacks=[{coins:50000,discount:0},{coins:100000,discount:10},{coins:200000,discount:20},{coins:350000,discount:30},{coins:600000,discount:40},{coins:1000000,discount:50}].map(({coins,discount})=>({id:'inmypocket.coins.'+coins,coins,discount,priceKRW:Math.round(coins*3000/50000*(100-discount)/100)}));
export interface VerifiedPurchase {transactionId:string;walletBalance:number;}
/** Implement on the native platform with server receipt verification before enabling IAP. */
export interface PurchaseGateway {
 readonly ready:boolean;
 purchaseAndVerify(productId:string):Promise<VerifiedPurchase>;
 restorePurchases():Promise<VerifiedPurchase[]>;
}
export class CoinShop {
 constructor(private gateway:PurchaseGateway|null=null){}
 get ready(){return this.gateway?.ready===true;}
 async purchase(productId:string){
  if(!coinPacks.some(p=>p.id===productId))throw Error('Unknown product');
  if(!this.gateway?.ready)throw Error('Store and receipt verification are not configured');
  return this.gateway.purchaseAndVerify(productId);
 }
}
